import json, os, sys
import numpy as np
from scipy.spatial.transform import Rotation
from scipy.optimize import least_squares
from rcb_client import Robot
from PIL import Image
ROOT='/app/output'
class Driver:
 def __init__(self, record=True):
  self.r=Robot(); self.s=self.r.spec(); self.o=self.r.observe(images=False); self.record=record
  self.orig=np.array(self.s['arm']['position_m']); self.axes=np.array(self.s['arm']['axis']); self.ee=np.array(self.s['arm']['end_effector']['position_m'])
 def fk(self,q,p=None):
  T=np.eye(4)
  for a,c,t in zip(self.axes,self.orig,q):
   R=Rotation.from_rotvec(a*t).as_matrix(); A=np.eye(4); A[:3,:3]=R; A[:3,3]=c-R@c; T=T@A
  if p is None:p=self.ee
  return T[:3,:3]@p+T[:3,3],T[:3,:3],T
 def world(self,p,R=None):
  b=self.o['proprio']['base_pose']; rb=Rotation.from_euler('z',b[2]).as_matrix(); return rb@p+np.array([b[0],b[1],0]),rb if R is None else rb@R
 def ik(self,target,R,q0=None):
  b=self.o['proprio']['base_pose']; rb=Rotation.from_euler('z',b[2]).as_matrix(); target=rb.T@(np.array(target)-[b[0],b[1],0]); R=rb.T@R
  if q0 is None:q0=np.array(self.o['proprio']['arm_pos'])
  def fun(q):
   p,r,_=self.fk(q); return np.r_[ (p-target)*5,Rotation.from_matrix(R.T@r).as_rotvec(),(q-q0)*0.003]
  lo=np.array([-np.inf,-2.24,-np.inf,-2.57,-np.inf,-2.09,-np.inf]); hi=-lo
  res=least_squares(fun,np.clip(q0,lo+1e-6,hi-1e-6),bounds=(lo,hi),max_nfev=400)
  if np.linalg.norm(fun(res.x)[:3])>0.025: print('IK error',fun(res.x)[:6])
  return res.x
 def step(self,a,images=False):
  self.o=self.r.step('delta',a,images=images)
  if self.o['done']: print('EPISODE',self.o['reason'])
  return self.o
 def command(self,kind,*args):
  if self.record:
   with open(ROOT+'/commands.jsonl','a') as f:f.write(json.dumps([kind,args])+'\n')
  return getattr(self,kind)(*args)
 def joints(self,q,g=0,maxsteps=100):
  q=np.array(q)
  for i in range(maxsteps):
   cur=np.array(self.o['proprio']['arm_pos']); d=q-cur
   if np.max(abs(d))<0.003 and i>=3:break
   self.step([0,0,0,*np.clip(d,-0.075,0.075),g])
   if self.o['done']:break
  print('joints',self.o['step'],np.round(self.o['proprio']['arm_pos'],3),'ee',np.round(self.world(self.fk(self.o['proprio']['arm_pos'])[0])[0],3))
 def move(self,target,R=None,g=0):
  if R is None:R=np.diag([1,-1,-1])
  self.joints(self.ik(target,np.array(R)),g)
 def base(self,x,y,yaw=None,g=0):
  if yaw is None:yaw=self.o['proprio']['base_pose'][2]
  for i in range(100):
   p=np.array(self.o['proprio']['base_pose']); d=np.array([x,y,yaw])-p
   if np.max(abs(d))<0.001:break
   d[:2]*=min(1,0.07/(np.linalg.norm(d[:2])+1e-10)); d[2]=np.clip(d[2],-.07,.07)
   self.step([*d,*([0]*7),g])
   if self.o['done']:break
  print('base',self.o['step'],self.o['proprio']['base_pose'])
 def wait(self,n=10,g=0):
  for i in range(n):
   self.step([0]*10+[g])
   if self.o['done']:break
 def snap(self,name='view'):
  self.o=self.r.observe(); json.dump(self.o['proprio'],open(ROOT+'/proprio.json','w'))
  for k,v in self.o['images'].items():Image.fromarray(v).save(ROOT+'/'+name+'_'+k+'.png')
  for k,v in self.o.get('depth',{}).items():np.save(ROOT+'/'+name+'_'+k+'_depth.npy',v)
  print({k:self.o[k] for k in ['step','done','reason','resets_left']})
 def points(self,name='view'):
  cam=self.s['cameras']['robot_wrist']; p,R,T=self.fk(self.o['proprio']['arm_pos'],np.array(cam['pose']['position_m'])); cp,rot=self.world(p,R)
  f=240/np.tan(np.deg2rad(cam['fovy_deg']/2)); D=np.load(ROOT+'/'+name+'_robot_wrist_depth.npy'); rgb=np.array(Image.open(ROOT+'/'+name+'_robot_wrist.png'))
  yy,xx=np.indices(D.shape); pose=cam['pose']; xyz=cp+(D[...,None])*(rot@np.array(pose['forward']))+((xx-319.5)*D/f)[...,None]*(rot@np.array(pose['right']))+((239.5-yy)*D/f)[...,None]*(rot@np.array(pose['up']))
  return rgb,D,xyz
if __name__=='__main__':
 d=Driver(record=False)
 for line in open(ROOT+'/commands.jsonl'):
  kind,args=json.loads(line); getattr(d,kind)(*args)
  if d.o['done']:break
 d.snap('final')
